with open('doc/budget.md') as f:
  content = f.read()
import re

# Find all rec codes with Advertisement designation
ad_pattern = re.compile(r'rec[A-Za-z0-9]+.*?Advertisement', re.DOTALL|re.IGNORECASE)
ad_codes = []
for m in ad_pattern.finditer(content):
  rec = re.search(r'rec[A-Za-z0-9]+', m.group(0))
  if rec:
    ad_codes.append(rec.group(0))
print(f'Advertisement rec codes: {set(ad_codes)}')

# For each ad code, find linked event ID
for rec in set(ad_codes):
  idx = content.find(rec)
  if idx >= 0:
    ctx = content[idx:min(len(content),idx+3000)]
